const items = $input.all();
const get = (row, names, fallback='') => {
  for (const name of names) {
    if (row[name] !== undefined && row[name] !== null && String(row[name]).trim() !== '') { const val = row[name]; if (String(val).toLowerCase().includes('не требуется') || String(val).toLowerCase().includes('опционально')) continue; return val; }
  }
  return fallback;
};
const bool = (v, d=false) => {
  if (v === undefined || v === null || String(v).trim() === '') return d;
  const s = String(v).toLowerCase().trim();
  return ['true','1','yes','да','дa','включить','вкл','реально'].includes(s);
};
const isQueued = (row) => {
  const status = String(get(row, ['Статус','status','Status'], '')).toLowerCase().trim();
  return !status || ['queued','ready','new','todo','новая','новый','в очередь','к генерации','готово к запуску'].includes(status);
};
const rows = items.map(i => i.json || {}).filter(isQueued);
const source = rows.length ? rows : [{
  'Статус':'Новая',
  'Тема публикации':'Онлайн-школа: как из одного вебинара получить 30 Reels и неделю контента',
  'Продукт / проект':'n8n Content Studio для онлайн-школ и экспертов',
  'Целевая аудитория':'Основатели онлайн-школ, продюсеры, методисты и маркетологи EdTech',
  'Meta-площадка':'Instagram Reels + Facebook post',
  'Цель публикации':'Получить заявки на аудит контент-воронки',
  'Тональность':'живой экспертный, уверенный, премиальный, без инфошума',
  'Исходные материалы':'фрагмент вебинара, скрин Telegram-бота, отзыв ученика, логотип школы',
  'Создавать видео?':'Нет',
  'Dry-run / демо без платных API':'Да',
  'Публиковать в Meta реально?':'Нет'
}];
return source.slice(0, 3).map((row, index) => ({ json: {
  source_row: get(row, ['row_number','Row','row','Номер строки'], index + 2),
  status: get(row, ['Статус','status','Status'], 'queued'),
  topic: get(row, ['Тема публикации','Тема','topic','Topic','idea'], 'Untitled topic'),
  product: get(row, ['Продукт / проект','Продукт','Проект','product','Product'], ''),
  audience: get(row, ['Целевая аудитория','Аудитория','audience','Audience'], ''),
  platform: get(row, ['Meta-площадка','Площадка Meta','Площадка','platform','Platform'], 'Instagram Reels'),
  goal: get(row, ['Цель публикации','Цель','goal','Goal'], ''),
  tone: get(row, ['Тональность','Стиль','tone','Tone'], 'экспертно, коротко, практично'),
  assets: get(row, ['Исходные материалы','Материалы','assets','Assets'], ''),
  render_video: bool(get(row, ['Создавать видео?','render_video','RenderVideo'], ''), false),
  dry_run: bool(get(row, ['Dry-run / демо без платных API','Демо без платных API','dry_run','DryRun'], ''), true),
  meta_publish_live: bool(get(row, ['Публиковать в Meta реально?','Живая публикация Meta','meta_publish_live','MetaPublishLive'], ''), false),
  avatar_id: get(row, ['ID аватара HeyGen (опционально)','ID аватара HeyGen','HeyGen avatar_id','avatar_id','AvatarId'], 'PASTE_HEYGEN_AVATAR_ID'),
  voice_id: get(row, ['ID голоса HeyGen (опционально)','ID голоса HeyGen','HeyGen voice_id','voice_id','VoiceId'], 'PASTE_HEYGEN_VOICE_ID'),
  telegram_chat_id: get(row, ['Telegram ID для уведомления (опционально)','Telegram chat ID','telegram_chat_id','TelegramChatId'], ''),
  admin_chat_id: get(row, ['Admin chat ID','admin_chat_id','AdminChatId','Telegram ID для уведомления (опционально)'], '')
} }));

const base = $node['04 Код: собрать бриф для AI'].json;
const message = $json.output?.find?.((x) => x.type === 'message') || $json.output?.[0];
const raw = String(message?.content?.find?.((p) => p.type === 'output_text')?.text || message?.content?.[0]?.text || $json.text || '').trim();
function parseJson(s) {
  const clean = String(s || '').replace(/^\s*```json\s*/i,'').replace(/^\s*```\s*/i,'').replace(/\s*```\s*$/,'').trim();
  try { return JSON.parse(clean); } catch(e) { const m = clean.match(/\{[\s\S]*\}/); if (m) return JSON.parse(m[0]); throw e; }
}
let data;
try { data = parseJson(raw); } catch (e) {
  data = { status: 'needs_review', content_angle: 'AI output could not be parsed', caption_short: '', caption_long: raw.slice(0, 2000), reels_script: '', scene_plan: '', visual_prompt: '', hashtags: '', cta: '', meta_publish_copy: '', quality_notes: 'Parser fallback: ' + e.message };
}
return [{ json: { ...base, raw_model_output: raw, ...data } }];

const video_id = $json.data?.video_id || $json.data?.id || $json.video_id || $json.id || '';
if (!video_id) throw new Error('HeyGen did not return video_id. Check account/API body before retrying paid render.');
return [{ json: { ...$node['07 Код: подготовить запрос HeyGen avatar video'].json, heygen_video_id: video_id } }];

const base = $node['10 Код: проверить ID видео HeyGen'].json;
const url = $json.data?.video_url || $json.data?.captioned_video_url || $json.video_url || '';
const status = $json.data?.status || $json.status || (url ? 'completed' : 'processing');
return [{ json: { ...base, heygen_status: status, heygen_video_url: url || 'pending: check HeyGen status later', asset_mode: 'heygen_live_requested' } }];

return [{ json: {
  ...$json,
  heygen_video_id: 'mock-video-not-rendered',
  heygen_status: 'mock_avatar_video_ready',
  heygen_video_url: 'mock://avatar-video/vertical-1080x1920.mp4',
  asset_mode: 'dry_run_mock_video',
  video_render_notes: 'Видео с аватаром не рендерилось платно. Это mock-результат для демонстрации архитектуры.'
} }];

return [{ json: {
  ...$json,
  should_generate_voiceover: Boolean(!$json.dry_run && $json.render_video),
  voiceover_request: {
    provider: 'OpenAI TTS / ElevenLabs / HeyGen Voice',
    language: 'ru',
    text: String($json.reels_script || $json.caption_short || $json.topic || '').slice(0, 2500),
    voice: $json.voice_id || 'production_voice_from_credentials'
  }
}}];

return [{ json: {
  ...$node['14 Код: подготовить запрос озвучки'].json,
  voiceover_status: 'voiceover_api_requested',
  voiceover_audio_url: $json.audio_url || $json.url || 'production://voiceover.mp3',
  voiceover_provider: 'production_tts_api'
}}];

return [{ json: {
  ...$json,
  voiceover_status: 'mock_voiceover_ready',
  voiceover_audio_url: 'mock://voiceover/russian-narration.mp3',
  voiceover_provider: 'mock_safe_mode',
  voiceover_notes: 'Озвучка не создавалась платно. Это mock для демонстрации архитектуры.'
}}];

const sessionId = 'content-studio-' + String($json.source_row || 'demo') + '-' + Date.now();
return [{
  json: {
    ...$json,
    renderer_session_id: sessionId,
    should_generate_subtitles: Boolean(!$json.dry_run && $json.render_video),
    subtitles_request: {
      provider: 'Local Python renderer + FFmpeg ASS/SRT',
      endpoint: 'http://reels-renderer:8099/render-subtitles',
      session_id: sessionId,
      language: 'ru',
      format: 'ass+srt',
      audio_url: $json.voiceover_audio_url,
      script: $json.reels_script || $json.caption_short || $json.topic,
      style: {
        preset: 'reels_readable_lower_third',
        font: 'Montserrat Black',
        max_words_on_screen: 3,
        safe_area: 'no face/CTA overlap',
        accent_words: ['важно', 'результат', 'бот', 'контент', 'лиды']
      }
    }
  }
}];

const source = $node['18 Код: подготовить запрос субтитров'].json;
const out = $json || {};
return [{
  json: {
    ...source,
    subtitles_status: out.status || 'local_python_subtitles_ready',
    subtitles_srt: out.srt || out.subtitles_srt || out.srt_url || 'renderer://subtitles.srt',
    subtitles_ass: out.ass || out.subtitles_ass || out.ass_url || 'renderer://subtitles.ass',
    subtitles_provider: 'local_python_ffmpeg_renderer',
    renderer_session_id: out.session_id || source.renderer_session_id
  }
}];

const script = String($json.reels_script || $json.caption_short || $json.topic || '').trim();
const chunks = script.split(/(?<=[.!?])\s+/).filter(Boolean).slice(0, 6);
const srt = chunks.length ? chunks.map((line, i) => {
  const start = String(i * 4).padStart(2, '0');
  const end = String((i + 1) * 4).padStart(2, '0');
  return (i + 1) + '\n00:00:' + start + ',000 --> 00:00:' + end + ',000\n' + line;
}).join('\n\n') : '1\n00:00:00,000 --> 00:00:04,000\nСубтитры будут созданы из сценария Reels.';
return [{ json: { ...$json, subtitles_status: 'mock_subtitles_ready', subtitles_srt: srt, subtitles_provider: 'mock_srt_from_script' } }];

return [{
  json: {
    ...$json,
    final_material_status: $json.dry_run ? 'mock_final_video_ready' : 'local_python_render_ready',
    final_video_asset_url: String($json.heygen_video_url || '').startsWith('http')
      ? $json.heygen_video_url
      : 'mock://final-meta-reels/avatar-video-voiceover-subtitles.mp4',
    final_material_notes: 'Production render: локальный Python + FFmpeg собирает вертикальный 9:16 ролик, накладывает озвучку и ASS/SRT субтитры.',
    render_stack: 'HeyGen avatar video + TTS voiceover + Local Python/FFmpeg subtitles/render + Meta Graph API'
  }
}];

return [{ json: {
  ...$json,
  meta_publication_status: 'real_meta_api_requested',
  meta_publication_id: $json.id || $json.post_id || 'meta_api_response_id',
  meta_publication_url: $json.permalink_url || 'production://meta-post-url',
  'Статус Meta-публикации': 'Реальная Meta Graph API публикация запрошена',
  'ID публикации Meta / mock': $json.id || $json.post_id || 'meta_api_response_id',
  'Ссылка публикации Meta / mock': $json.permalink_url || 'production://meta-post-url'
}}];

const postId = 'mock_meta_post_' + Date.now();
return [{ json: {
  ...$json,
  meta_publication_status: 'mock_published_to_meta_platforms',
  meta_publication_id: postId,
  meta_publication_url: 'mock://meta/instagram-facebook/' + postId,
  'Статус Meta-публикации': 'Mock опубликовано на Instagram/Facebook',
  'ID публикации Meta / mock': postId,
  'Ссылка публикации Meta / mock': 'mock://meta/instagram-facebook/' + postId
}}];
